static __forceinline void build_cage_mesh(Path *path, char *texture_a, char *texture_b)
{
    int mesh_cursor;
    int width_cells_;
    path->strip_mesh->RequestVertices((path->width_cells + 1) * (path->segment_count + 1));
    path->strip_mesh->RequestFaceQuads(2 * path->width_cells * path->segment_count);

    cRFaceQuad *facequads = path->strip_mesh->facequads;
    Vector3 *vertices = path->strip_mesh->vertices;

    for (int row = 0; row <= path->segment_count; ++row)
    {
        int column = 0;
        for (; column <= path->width_cells; ++column)
        {
            if (row != path->segment_count)
            {
                Vector3 lateral_offset =
                    path->primary_samples[row].transform.basis_right *
                    ((float)column - (float)path->width_cells * 0.5f);
                Vector3 generated_position =
                    lateral_offset + path->primary_samples[row].transform.position;
                Vector3 *vertex = &vertices[column + row * (path->width_cells + 1)];
                *vertex = generated_position;
            }
            else
            {
                Vector3 generated_position =
                    (path->primary_samples[row - 1].transform.position + Vector3(0.0f, 0.0f, 1.0f)) +
                    (path->primary_samples[row - 1].transform.basis_right *
                     ((float)column - (float)path->width_cells * 0.5f));
                Vector3 *vertex = &vertices[column + row * (path->width_cells + 1)];
                *vertex = generated_position;
            }
        }
    }

    mesh_cursor = 0;
    for (; mesh_cursor < path->segment_count; ++mesh_cursor)
    {
        width_cells_ = 0;
        if (path->width_cells > 0)
        {
            float v0 = (float)(mesh_cursor % 8) * 0.125f;
            float v1 = (float)(mesh_cursor % 8 + 1) * 0.125f;
            int next_column;
            do
            {
                next_column = width_cells_ + 1;
                float u0 = (float)width_cells_ * 0.125f;
                float u1 = (float)(width_cells_ + 1) * 0.125f;
                for (int face_index = 0; face_index < 2; ++face_index)
                {
                    int face_offset = 2 * width_cells_ + 2 * mesh_cursor * path->width_cells + face_index;
                    if (face_index == 0)
                    {
                        facequads[face_offset].header_word = 0;
                        facequads[face_offset].vertex_0 =
                            width_cells_ +
                            mesh_cursor * ((unsigned short)path->width_cells + 1);
                        facequads[face_offset].vertex_1 =
                            mesh_cursor * ((unsigned short)path->width_cells + 1) +
                            width_cells_ + 1;
                        facequads[face_offset].vertex_2 =
                            (mesh_cursor + 1) * ((unsigned short)path->width_cells + 1) +
                            width_cells_ + 1;
                        facequads[face_offset].vertex_3 =
                            width_cells_ +
                            (mesh_cursor + 1) * ((unsigned short)path->width_cells + 1);
                        if (((width_cells_ ^ mesh_cursor) & 1) == 0)
                            facequads[face_offset].texture_ref = g_texture_refs.Add(texture_a, 0, 0);
                        else
                            facequads[face_offset].texture_ref = g_texture_refs.Add(texture_a, 0, 0);
                    }
                    else
                    {
                        facequads[face_offset].header_word = 0;
                        facequads[face_offset].vertex_0 =
                            mesh_cursor * ((unsigned short)path->width_cells + 1) +
                            width_cells_ + 1;
                        facequads[face_offset].vertex_1 =
                            width_cells_ +
                            mesh_cursor * ((unsigned short)path->width_cells + 1);
                        facequads[face_offset].vertex_2 =
                            width_cells_ +
                            (mesh_cursor + 1) * ((unsigned short)path->width_cells + 1);
                        facequads[face_offset].vertex_3 =
                            (mesh_cursor + 1) * ((unsigned short)path->width_cells + 1) +
                            width_cells_ + 1;
                        if (((width_cells_ ^ mesh_cursor) & 1) == 0)
                            facequads[face_offset].texture_ref = g_texture_refs.Add(texture_b, 0, 0);
                        else
                            facequads[face_offset].texture_ref = g_texture_refs.Add(texture_b, 0, 0);
                    }
                    if (face_index == 0)
                    {
                        facequads[face_offset].uv[0].u = u0;
                        facequads[face_offset].uv[0].v = v0;
                        facequads[face_offset].uv[1].u = u1;
                        facequads[face_offset].uv[1].v = v0;
                        facequads[face_offset].uv[2].u = u1;
                        facequads[face_offset].uv[2].v = v1;
                        facequads[face_offset].uv[3].u = u0;
                        facequads[face_offset].uv[3].v = v1;
                    }
                    else
                    {
                        facequads[face_offset].uv[0].u = u1;
                        facequads[face_offset].uv[0].v = v0;
                        facequads[face_offset].uv[1].u = u0;
                        facequads[face_offset].uv[1].v = v0;
                        facequads[face_offset].uv[2].u = u0;
                        facequads[face_offset].uv[2].v = v1;
                        facequads[face_offset].uv[3].u = u1;
                        facequads[face_offset].uv[3].v = v1;
                    }
                }
                width_cells_ = next_column;
            } while (next_column < path->width_cells);
        }
    }

}

