static __forceinline void build_cage_mesh(Path *path, char *texture_a, char *texture_b, int &mesh_cursor, int &width_cells_)
{
    path->strip_mesh->RequestVertices((path->width_cells + 1) * (path->segment_count + 1));
    path->strip_mesh->RequestFaceQuads(2 * path->width_cells * path->segment_count);

    cRFaceQuad *facequads = path->strip_mesh->facequads;
    Vector3 *vertices = path->strip_mesh->vertices;

    for (mesh_cursor = 0; mesh_cursor <= path->segment_count; ++mesh_cursor)
    {
        width_cells_ = 0;
        for (; width_cells_ <= path->width_cells; ++width_cells_)
        {
            if (mesh_cursor != path->segment_count)
            {
                Vector3 lateral_offset =
                    path->primary_samples[mesh_cursor].transform.basis_right *
                    ((float)width_cells_ - (float)path->width_cells * 0.5f);
                Vector3 generated_position =
                    lateral_offset + path->primary_samples[mesh_cursor].transform.position;
                Vector3 *vertex = &vertices[width_cells_ + mesh_cursor * (path->width_cells + 1)];
                *vertex = generated_position;
            }
            else
            {
                Vector3 generated_position =
                    (path->primary_samples[mesh_cursor - 1].transform.position + Vector3(0.0f, 0.0f, 1.0f)) +
                    (path->primary_samples[mesh_cursor - 1].transform.basis_right *
                     ((float)width_cells_ - (float)path->width_cells * 0.5f));
                Vector3 *vertex = &vertices[width_cells_ + mesh_cursor * (path->width_cells + 1)];
                *vertex = generated_position;
