    do
    {
        float middle_f = (float)middle;
        out_angle = middle_f * 0.18479957f;
        ((AttachmentSample *)((char *)middle_primary + middle_offset))->center_x =
            (middle_primary[50].center_x - middle_primary[0].center_x) * middle_f *
