        ((AttachmentSample *)((char *)secondary_samples + middle_offset))->transform =
            ((AttachmentSample *)((char *)middle_primary + middle_offset))->transform;
        Vector3 secondary_offset =
            ((AttachmentSample *)((char *)middle_primary + middle_offset))
                ->transform.basis_up *
            0.49000001f;
        Vector3 *secondary_position =
            &((AttachmentSample *)((char *)secondary_samples + middle_offset))
                 ->transform.position;
        secondary_position->x += secondary_offset.x;
        secondary_position->y += secondary_offset.y;
        secondary_position->z += secondary_offset.z;
        ++middle;
        middle_offset += sizeof(AttachmentSample);
    } while (middle_offset < 50 * (int)sizeof(AttachmentSample));

}

}

static __forceinline void build_halfpipe_mesh(Path *path, char *texture_a, char *texture_b, float &out_angle)
{
    path->strip_mesh->RequestVertices((path->width_cells + 1) * (path->segment_count + 1));
    path->strip_mesh->RequestFaceQuads(2 * path->segment_count * path->width_cells);

    cRFaceQuad *facequads = path->strip_mesh->facequads;
    Vector3 *vertices = path->strip_mesh->vertices;

}

