static __forceinline void initialize_halfpipe_ends(Path *path, int &sample_step)
{
    sample_step = 0;
    int lead_sample_offset = 0;
    do
    {
        float index = (float)sample_step;
        float angle_base = index * 0.0625f;
        float angle = angle_base * 3.1415927f + 1.5707964f;
        float depth = ((0.5f - Sin(angle) * 0.5f) * 0.94999999f + 0.050000001f) * 4.0f;
        ((AttachmentSample *)((char *)path->primary_samples + lead_sample_offset))->center_x =
            (float)path->width_cells * 0.5f - 4.0f;
        ((AttachmentSample *)((char *)path->primary_samples + lead_sample_offset))
            ->rotation_scalar_98 = 0.0f;
        ((AttachmentSample *)((char *)path->primary_samples + lead_sample_offset))
            ->rotation_scalar_94 = 0.0f;
        ((AttachmentSample *)((char *)path->primary_samples + lead_sample_offset))
            ->special_scalar = (depth * depth + 16.0f) / (depth + depth);
        ((AttachmentSample *)((char *)path->primary_samples + lead_sample_offset))
            ->lateral_scale = 1.0f;
        ((AttachmentSample *)((char *)path->primary_samples + lead_sample_offset))
            ->transform.Identity();
        ((AttachmentSample *)((char *)path->primary_samples + lead_sample_offset))
            ->transform.position.x =
            ((AttachmentSample *)((char *)path->primary_samples + lead_sample_offset))
                ->center_x;
        ((AttachmentSample *)((char *)path->primary_samples + lead_sample_offset))
            ->transform.position.y = 0.0f;
        ((AttachmentSample *)((char *)path->primary_samples + lead_sample_offset))
            ->transform.position.z = index;
        ((AttachmentSample *)((char *)path->primary_samples + lead_sample_offset))
            ->delta_length = 1.0f;

        ((AttachmentSample *)((char *)path->secondary_samples + lead_sample_offset))
            ->transform.Identity();
        ((AttachmentSample *)((char *)path->secondary_samples + lead_sample_offset))
            ->transform.position.x =
            ((AttachmentSample *)((char *)path->primary_samples + lead_sample_offset))
                ->center_x;
        ((AttachmentSample *)((char *)path->secondary_samples + lead_sample_offset))
            ->transform.position.y = 0.49000001f;
        ((AttachmentSample *)((char *)path->secondary_samples + lead_sample_offset))
            ->transform.position.z = index;
        ((AttachmentSample *)((char *)path->secondary_samples + lead_sample_offset))
            ->delta_length = 1.0f;
        ++sample_step;
        lead_sample_offset += sizeof(AttachmentSample);
    } while (lead_sample_offset < 16 * (int)sizeof(AttachmentSample));

    sample_step = 0;
    do
    {
        int sample_index = sample_step + 50;
        float angle_base = 1.0f - (float)sample_step * 0.0625f;
        float angle = angle_base * 3.1415927f + 1.5707964f;
        float depth = ((0.5f - Sin(angle) * 0.5f) * 0.94999999f + 0.050000001f) * 4.0f;
        path->primary_samples[sample_index].center_x = 4.0f - (float)path->width_cells * 0.5f;
        path->primary_samples[sample_index].rotation_scalar_98 = 0.0f;
        path->primary_samples[sample_index].rotation_scalar_94 = 0.0f;
        path->primary_samples[sample_index].special_scalar =
            (depth * depth + 16.0f) / (depth + depth);
        path->primary_samples[sample_index].lateral_scale = 1.0f;
        path->primary_samples[sample_index].transform.Identity();
        path->primary_samples[sample_index].transform.position.x =
            path->primary_samples[sample_index].center_x;
        path->primary_samples[sample_index].transform.position.y = 0.0f;
        path->primary_samples[sample_index].transform.position.z = (float)sample_index;
        path->primary_samples[sample_index].delta_length = 1.0f;

        path->secondary_samples[sample_index].transform.Identity();
        path->secondary_samples[sample_index].transform.position.x =
            path->primary_samples[sample_index].center_x;
        path->secondary_samples[sample_index].transform.position.y = 0.49000001f;
        path->secondary_samples[sample_index].transform.position.z = (float)sample_index;
        path->secondary_samples[sample_index].delta_length = 1.0f;
        ++sample_step;
    } while (sample_step < 16);

