static __forceinline void build_loop_mesh(Path *path, AttachmentSample *const &primary_bank, char *texture_a, char *texture_b, int &row)
{
    path->strip_mesh->RequestVertices((path->width_cells + 1) * (path->segment_count + 1));
    path->strip_mesh->RequestFaceQuads(2 * path->width_cells * path->segment_count);

    Vector3* vertices = path->strip_mesh->vertices;
    cRFaceQuad* facequads = path->strip_mesh->facequads;

    int column;
    int face_index;

    for (row = 0; row <= path->segment_count; ++row) {
        for (column = 0; column <= path->width_cells; ++column) {
            if (row != path->segment_count) {
                double lateral =
                    (float)column - (float)path->width_cells * 0.5f;
                Vector3 lateral_offset =
                    primary_bank[row].transform.basis_right * lateral;
                Vector3 generated_position =
                    primary_bank[row].transform.position + lateral_offset;
                Vector3* vertex =
                    &vertices[column + row * (path->width_cells + 1)];
                *vertex = generated_position;
            } else {
                double lateral =
                    (float)column - (float)path->width_cells * 0.5f;
                Vector3 lateral_offset =
                    primary_bank[row - 1].transform.basis_right * lateral;
                Vector3 endpoint = primary_bank[row - 1].transform.position
                    + Vector3(0.0f, 0.0f, 1.0f);
                Vector3 generated_position = endpoint + lateral_offset;
                Vector3* vertex =
                    &vertices[column + row * (path->width_cells + 1)];
                *vertex = generated_position;
            }
        }
    }

    for (row = 0; row < path->segment_count; ++row) {
        column = 0;
        if (path->width_cells > 0) {
            float v0 = (float)(row % 8) * 0.125f;
            float v1 = (float)(row % 8 + 1) * 0.125f;
            int next_column;
            do {
                face_index = 0;
                next_column = column + 1;
                float u0 = (float)column * 0.125f;
                float u1 = (float)(column + 1) * 0.125f;
                for (; face_index < 2; ++face_index) {
                    int face_array_index =
                        face_index
                        + 2 * (row * path->width_cells + column);
                    if (face_index == 0) {
                        facequads[face_array_index].header_word = 0;
                        facequads[face_array_index].vertex_0 = column + row * ((unsigned short)path->width_cells + 1);
                        facequads[face_array_index].vertex_1 = row * ((unsigned short)path->width_cells + 1) + column + 1;
                        facequads[face_array_index].vertex_2 =
                            (row + 1) * ((unsigned short)path->width_cells + 1) + column + 1;
                        facequads[face_array_index].vertex_3 =
                            column + (row + 1) * ((unsigned short)path->width_cells + 1);
                        if (((column ^ row) & 1) == 0)
                            facequads[face_array_index].texture_ref =
                                g_texture_refs.Add(texture_a, 0, 0);
                        else
                            facequads[face_array_index].texture_ref =
                                g_texture_refs.Add(texture_a, 0, 0);
                    } else {
                        facequads[face_array_index].header_word = 0;
                        facequads[face_array_index].vertex_0 = row * ((unsigned short)path->width_cells + 1) + column + 1;
                        facequads[face_array_index].vertex_1 = column + row * ((unsigned short)path->width_cells + 1);
                        facequads[face_array_index].vertex_2 =
                            column + (row + 1) * ((unsigned short)path->width_cells + 1);
                        facequads[face_array_index].vertex_3 =
                            (row + 1) * ((unsigned short)path->width_cells + 1) + column + 1;
                        if (((column ^ row) & 1) == 0)
                            facequads[face_array_index].texture_ref =
                                g_texture_refs.Add(texture_b, 0, 0);
                        else
                            facequads[face_array_index].texture_ref =
                                g_texture_refs.Add(texture_b, 0, 0);
                    }
                    if (face_index == 0) {
                        facequads[face_array_index].uv[0].u = u0;
                        facequads[face_array_index].uv[0].v = v0;
                        facequads[face_array_index].uv[1].u = u1;
                        facequads[face_array_index].uv[1].v = v0;
                        facequads[face_array_index].uv[2].u = u1;
                        facequads[face_array_index].uv[2].v = v1;
                        facequads[face_array_index].uv[3].u = u0;
                        facequads[face_array_index].uv[3].v = v1;
                    } else {
                        facequads[face_array_index].uv[0].u = u1;
                        facequads[face_array_index].uv[0].v = v0;
                        facequads[face_array_index].uv[1].u = u0;
                        facequads[face_array_index].uv[1].v = v0;
                        facequads[face_array_index].uv[2].u = u0;
                        facequads[face_array_index].uv[2].v = v1;
                        facequads[face_array_index].uv[3].u = u1;
                        facequads[face_array_index].uv[3].v = v1;
                    }
                }
                column = next_column;
            } while (next_column < path->width_cells);
        }
    }

}

